G1_G2.temporaryInitScript:
gradle.projectsEvaluated {
  def configuration = gradle.rootProject.findProject(':modules:configuration')
  if (configuration == null) return
  def buildDirectory = configuration.layout.buildDirectory
  ['integrationTest', 'systemTest'].each { tier ->
    configuration.tasks.register(tier, org.gradle.api.tasks.testing.Test) {
      testClassesDirs = configuration.sourceSets.test.output.classesDirs
      classpath = configuration.sourceSets.test.runtimeClasspath
      filter.includeTestsMatching('io.justsearch.configuration.TestProfileIsolationTest')
      doLast {
        def home = new File(systemProperties['user.home'])
        assert home == new File(buildDirectory.get().asFile, "test-profile/${tier}/home")
        def ort = new File(environment['JUSTSEARCH_ORT_OPTIMIZED_CACHE_DIR'])
        def expectedOrt = (System.getProperty('os.name').startsWith('Windows')
            ? new File(System.getProperty('java.io.tmpdir'), 'js-ort-test-configuration')
            : new File(buildDirectory.get().asFile, 'ort-optimized'))
        assert ort == expectedOrt
        logger.lifecycle("PROFILE_TIER ${tier}: home=${home} ort=${ort}")
      }
    }
  }
}
